def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    # Clues occupy parallel lines. Identify the coordinate that is constant
    # along each line and whose line colors are consistent.
    key_funcs = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: r - c,
    ]
    candidates = []
    for key in key_funcs:
        by_key = {}
        valid = True
        for r, c, color in points:
            k = key(r, c)
            if k in by_key and by_key[k] != color:
                valid = False
                break
            by_key[k] = color
        if valid:
            candidates.append((len(by_key), key, by_key))
    if not candidates:
        raise ValueError("nonzero clues do not form monochromatic parallel lines")

    # The clue lines give a repeating sequence. Infer the smallest period for
    # which every residue is represented and all observed colors agree.
    _, key, known = max(candidates, key=lambda candidate: candidate[0])
    period = None
    residue_color = None
    for p in range(1, max(h, w) + 1):
        mapping = {}
        for k, color in known.items():
            residue = k % p
            if residue in mapping and mapping[residue] != color:
                break
            mapping[residue] = color
        else:
            if len(mapping) == p:
                period, residue_color = p, mapping
                break
    if period is None:
        raise ValueError("could not infer a complete period from clue lines")

    return [[residue_color[key(r, c) % period] for c in range(w)] for r in range(h)]
